        switch value {
        case .workspaceChangesWereRestored: return string(.messageWorkspaceChangesWereRestored)
        case .workspaceChangeCancelled: return string(.uiWorkspaceChangeCancelled)
        case .branchReuseBehind(let branch, let count, let base, let isWorkspace):
            return string(.uiReusedBranchIsCommitsBehindCommitsWereKept(branch, count, isWorkspace ? string(.uiWorkspaceHEAD) : base))
        case .unmanagedWorktrees(let paths): return string(.messageRepositoryIsStillUsedByWorktreesOutsideModu(paths.joined(separator: "\n")))
        case .branchReuseComparisonUnavailable(let arg1, let arg2, let arg3, let isWorkspace): return string(.messageReusedBranchButComparisonWithIsUnavailable(arg1, isWorkspace ? string(.uiWorkspaceHEAD) : arg2, message(arg3)))
        case .repositoryNameCollision(let arg1): return string(.messageDifferentURLsDeriveSameRepositoryName(arg1))
        case .duplicateURL: return string(.messageDuplicateURL)
        case .diagnostic: return string(.uiCouldnTCompleteOperationSeeDetailsForDiagnostic)
        case .joined(let values, let separator): return values.map(message).joined(separator: separator)
        case .workspaceRepositoryIsUnavailable(let arg1): return string(.messageWorkspaceRepositoryIsUnavailable(message(arg1)))
        case .repositoryNameIsAlreadyRegistered(let arg1): return string(.messageRepositoryNameIsAlreadyRegistered(arg1))
        case .repositoryTargetAlreadyExists(let arg1): return string(.messageRepositoryTargetAlreadyExists(arg1))
